@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState Warehouse
@inject InventoryAlertService AlertService
@implements IAsyncDisposable

<PageTitle>Dashboard – @Warehouse.CurrentWarehouse.Name</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="alert alert-info d-flex align-items-center gap-2" role="alert">
    <strong>Active site:</strong> @Warehouse.CurrentWarehouse.Name (@Warehouse.CurrentWarehouse.Id)
</div>

<div class="card mb-4" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text display-6">
            @if (AlertService.CurrentAlertCount > 0)
            {
                <span class="text-danger">@AlertService.CurrentAlertCount items below minimum</span>
            }
            else
            {
                <span class="text-success">All stock levels OK</span>
            }
        </p>
        <small class="text-muted">Polling every 10 seconds · Last check: @_lastPoll?.ToString("HH:mm:ss")</small>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime? _lastPoll;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to warehouse changes so we re-render and restart polling.
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            await PollNow();
            StateHasChanged();
        });
        Warehouse.OnChange += _warehouseHandler;

        // Subscribe to alert changes (triggered by our own polling, but the
        // event also reaches the sidebar AlertBadge — that's the point).
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Initial poll, then start timer.
        await PollNow();
        StartPolling();
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await PollNow();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose / warehouse switch.
        }
    }

    private async Task PollNow()
    {
        await AlertService.RefreshAsync(Warehouse.CurrentWarehouse.Id);
        _lastPoll = DateTime.Now;
    }

    public async ValueTask DisposeAsync()
    {
        StopPolling();

        if (_warehouseHandler is not null)
            Warehouse.OnChange -= _warehouseHandler;

        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

